from pathlib import Path
from PIL import Image
import json
P=Path(__file__).resolve().parents[1];G=P/'gallery';G.mkdir(exist_ok=True)
rows=json.loads((P/'reference_observations.json').read_text())['notes']
for r in rows:
 for suffix in ['comparison','views']:
  f=P/'previews'/f"{r['id']}_{suffix}.jpg";im=Image.open(f);im.thumbnail((1800,1000));im.save(G/f.name,quality=85)
 for v in ['front','side','threequarter','rear','backthreequarter','portrait']:
  im=Image.open(P/'renders'/f"{r['id']}_{v}.png").convert('RGB');im.save(G/f"{r['id']}_{v}.jpg",quality=85)
data=[{'id':r['id'],'name':r['name']} for r in rows]
html='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Ninja dogs | Blender model review</title><style>*{box-sizing:border-box}body{margin:auto;max-width:1500px;background:#eee6d7;color:#262a2e;font:16px system-ui;padding:24px}h1{margin:0}p{line-height:1.5}nav{display:flex;gap:8px;flex-wrap:wrap;margin:16px 0}button,select{padding:12px;border:1px solid #555;border-radius:6px;background:#fff;color:#222;font:inherit;cursor:pointer}button[aria-pressed=true]{background:#273b43;color:white}img{display:block;max-width:100%;max-height:78vh;margin:auto;object-fit:contain}#controls{display:flex;gap:12px;align-items:center;flex-wrap:wrap}#title{flex:1;min-width:180px}footer{margin-top:24px;color:#505050}</style><h1>Ninja dogs</h1><p>Ten editable static Blender models based on the approved drawings. Compare the illustration and actual model, or inspect every side. These are posed sculptures, without rigs or animations.</p><nav id="dogs" aria-label="Choose dog"></nav><div id="controls"><button id="prev" aria-label="Previous dog">← Previous</button><h2 id="title"></h2><button id="next" aria-label="Next dog">Next →</button><select id="view" aria-label="View"><option value="comparison">Reference comparison</option><option value="views">Five-view sheet</option><option value="threequarter">Three-quarter</option><option value="front">Front</option><option value="side">Side</option><option value="rear">Rear</option><option value="backthreequarter">Back three-quarter</option><option value="portrait">Portrait</option></select></div><img id="preview" alt=""><footer>Original references remain unchanged. Hidden sides are interpreted; fine painted fur, embroidery, wear and magical effects are simplified. Open the individual .blend files for separate anatomy, fur and equipment objects.</footer><script>const dogs=DATA;let current=0;const nav=document.querySelector('#dogs'),picture=document.querySelector('#preview'),view=document.querySelector('#view');dogs.forEach((d,i)=>{const b=document.createElement('button');b.textContent=d.id+' '+d.name;b.onclick=()=>{current=i;show()};nav.appendChild(b)});function show(){let d=dogs[current];document.querySelector('#title').textContent=d.id+' / '+d.name;picture.src=d.id+'_'+view.value+'.jpg';picture.alt=d.name+' — '+view.options[view.selectedIndex].text;[...nav.children].forEach((b,i)=>b.setAttribute('aria-pressed',i===current));}document.querySelector('#prev').onclick=()=>{current=(current+9)%10;show()};document.querySelector('#next').onclick=()=>{current=(current+1)%10;show()};view.onchange=show;show();</script></html>'''.replace('DATA',json.dumps(data))
(G/'index.html').write_text(html)
print('Gallery generated',len(list(G.glob('*.jpg'))),'images')
